import numpy as np
import time
from scipy.optimize import minimize


def _R_from_h(h):
    L = np.convolve(h, h)
    L = np.concatenate(([0.0], L, [0.0]))
    s = L[:-1] ** 2 + L[:-1] * L[1:] + L[1:] ** 2
    l2sq = s.sum() / 3.0
    l1 = h.sum() ** 2
    linf = L.max()
    if l1 <= 0 or linf <= 0:
        return 0.0
    return l2sq / (l1 * linf)


def _build(N, k, A):
    k = int(round(k))
    k = max(0, min(N // 2, k))
    h = np.ones(N)
    if k > 0:
        h[:k] = A
        h[N - k:] = A
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5

    N = 2000

    def R_params(p):
        k, A = p
        A = max(1.0, A)
        return -_R_from_h(_build(N, k, A))

    # Coarse grid
    best = (-1.0, 0, 1.0)
    for k in [0, 1, 2, 3, 5, 8, 12, 20, 30, 50, 80, 120, 200, 300, 500, 800, 1000]:
        for A in [1.0, 1.2, 1.5, 2.0, 3.0, 5.0, 8.0, 12.0, 20.0]:
            r = _R_from_h(_build(N, k, A))
            if r > best[0]:
                best = (r, k, A)
        if time.process_time() > deadline:
            break

    # Refine with Nelder-Mead from several starts
    starts = [(best[1], best[2])]
    for k0 in [best[1], max(1, best[1] // 2), best[1] * 2, 5, 20, 50]:
        for A0 in [best[2], 1.5, 3.0, 6.0]:
            starts.append((k0, A0))

    best_r, best_k, best_A = best
    for (k0, A0) in starts:
        if time.process_time() > deadline:
            break
        try:
            res = minimize(R_params, [float(k0), float(A0)], method="Nelder-Mead",
                           options={"xatol": 0.5, "fatol": 1e-8, "maxiter": 400})
            k, A = res.x
            A = max(1.0, A)
            r = _R_from_h(_build(N, k, A))
            if r > best_r:
                best_r, best_k, best_A = r, k, A
        except Exception:
            pass

    h = _build(N, best_k, best_A)

    # If start is better, keep it
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            if _R_from_h(s) > best_r:
                return s

    return h

