def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = np.convolve(h, h)
    inf = L.max()
    if inf <= 0:
        return 0.0
    num = np.sum(L * L) + np.sum(L[:-1] * L[1:])
    return (num / 3.0) / (s * s * inf)


def resample(h, N):
    h = np.asarray(h, dtype=float)
    if h.size == N:
        return h.copy()
    x = np.linspace(0, 1, h.size)
    xi = np.linspace(0, 1, N)
    return np.interp(xi, x, h)


def R_grad_step(h, cur):
    """One efficient move: try scaling a contiguous block via bounded search."""
    return h, cur


