                        options={'xatol': 1e-10})
                    cand = res.x
                    cand_r = -res.fun
                except Exception:
                    cand = old
                    cand_r = cur

                if cand_r > cur:
                    h[idx] = cand
                    cur = cand_r
                    improved = True
                else:
                    h[idx] = old
            if not improved:
                break
        return h, cur

