    n = h.size
    xf = (np.arange(n * f) + 0.5) / f - 0.5
    P = PchipInterpolator(np.arange(n), h)
    out = P(xf)
    out = np.clip(out, 0, None)
    m = out.max()
    if m > 0:
        out = out / m
    return out


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90
    rng = np.random.default_rng(2024)

    if start is not None:
        base = np.asarray(start, dtype=float).copy()
        base = np.clip(base, 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = base / base.max()

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.6f (N=%d)" % (bestR, best.size))

    def exact_obj(x):
        xc = np.clip(x, 0, None)
        R, g = _R_and_grad(xc)
        g = g * (x > 0)
        return -R, -g

    def make_pen(mu):
        def f(x):
            xc = np.clip(x, 0, None)
            P, g = _penalty_and_grad(xc, mu)
            g = g * (x > 0)
            return P, g
        return f

    def coord_sweep(h, cur, n_passes):
        n = h.size
        for _ in range(n_passes):
            if time.process_time() > deadline:
                return h, cur
            improved = False
            order = rng.permutation(n)
            for idx in order:
                if time.process_time() > deadline:
                    return h, cur
                old = h[idx]
                hi = max(4.0 * old, 1.0)

                def neg_r(alpha):
                    h[idx] = alpha
                    return -R_of(h)

                try:
                    res = minimize_scalar(neg_r, bounds=(0.0, hi),
                                          method='bounded',
                                          options={'xatol': 1e-9})
                    cand = res.x
                    cand_r = -res.fun
                except Exception:
                    cand = old
                    cand_r = cur
                if cand_r > cur + 1e-15:
                    h[idx] = cand
                    cur = cand_r
                    improved = True
                else:
                    h[idx] = old
            if not improved:
                break
        return h, cur

    def targeted_sweep(h, cur, max_passes=2):
        n = h.size
        for p in range(max_passes):
            if time.process_time() > deadline - 1.0:
                break
            Lf = _knots(h)
            mx = Lf.max()
            if mx <= 0:
                break
            plate = np.where(Lf > 0.98 * mx)[0]
            cand = set()
            for k in plate:
                cand.add(int(np.clip(k - 1, 0, n - 1)))
                cand.add(int(np.clip(k, 0, n - 1)))
            # heights adjacent to zero blocks
            zero_idx = np.where(h <= 0)[0]
            if zero_idx.size > 0:
                nbrs = set()
                for i in zero_idx:
                    if i > 0 and h[i - 1] > 0:
                        nbrs.add(int(i))
                    if i < n - 1 and h[i + 1] > 0:
                        nbrs.add(int(i))
                nbrs = list(nbrs)
                if len(nbrs) > 100:
                    sel = rng.choice(len(nbrs), size=100, replace=False)
                    nbrs = [nbrs[j] for j in sel]
                cand.update(nbrs)
            cand = list(cand)
            if len(cand) > 400:
                sel = rng.choice(len(cand), size=400, replace=False)
                cand = [cand[j] for j in sel]
            improved = False
            for idx in cand:
                if time.process_time() > deadline - 1.0:
                    break
                old = h[idx]
                hi = 3.0 * old + 0.1

                def neg_r(alpha):
                    h[idx] = alpha
                    return -R_of(h)

                try:
                    res = minimize_scalar(neg_r, bounds=(0.0, hi),
                                          method='bounded',
                                          options={'xatol': 1e-8})
                    candv = res.x
                    cand_r = -res.fun
                except Exception:
                    candv = old
                    cand_r = cur
                if cand_r > cur + 1e-12:
                    h[idx] = candv
                    cur = cand_r
                    improved = True
                else:
                    h[idx] = old
            print("coord-target pass%d R=%.6f (N=%d)" % (p + 1, cur, n))
            if not improved:
                break
        return h, cur

