            print("ladder up4 R=%.6f (N=%d)" % (bestR, best.size))
        if time.process_time() < deadline - 2.0 and best.size < 100000:
            up8 = np.repeat(best, 2)
            hu, cu = run_schedule(up8, mu_list[12:])
            hu, cu = polish(hu, cu)
            if cu > bestR:
