import numpy as np
import time
from scipy.optimize import minimize, minimize_scalar
from scipy.interpolate import PchipInterpolator
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    num = np.sum(L[:-1]**2 + L[:-1]*L[1:] + L[1:]**2) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2*a + b)
    dq[1:] += (a + 2*b)
    dq /= 3.0
    return num, dq, h.sum(), Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _penalty_and_grad(h, mu):
    n = h.size
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(n)
    num, dq, s, Lf = _num_and_dq(h)
    s2 = s * s
    P = -num / s2
    gLf = -dq / s2
    grad = _backprop(gLf, h)
    grad += 2.0 * num / (s2 * s)
    r = np.maximum(Lf - 1.0, 0.0)
    if np.any(r > 0):
        P += mu * np.sum(r * r)
        w = 2.0 * mu * r
        grad += _backprop(w, h)
    return P, grad


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _upsample_interp(h, f):
    h = np.asarray(h, dtype=float)
    n = h.size
    xf = (np.arange(n * f) + 0.5) / f - 0.5
    P = PchipInterpolator(np.arange(n), h)
    out = P(xf)
    out = np.clip(out, 0, None)
    m = out.max()
    if m > 0:
        out = out / m
    return out


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85
    rng = np.random.default_rng(2024)

    if start is not None:
        base = np.asarray(start, dtype=float).copy()
        base = np.clip(base, 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = base / base.max()

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.6f (N=%d)" % (bestR, best.size))

    def make_pen(mu):
        def f(x):
            xc = np.clip(x, 0, None)
            P, g = _penalty_and_grad(xc, mu)
            g = g * (x > 0)
            return P, g
        return f

    def coord_sweep(h, cur, n_passes):
        n = h.size
        for _ in range(n_passes):
            if time.process_time() > deadline:
                return h, cur
            improved = False
            order = rng.permutation(n)
            for idx in order:
                if time.process_time() > deadline:
                    return h, cur
                old = h[idx]
                hi = max(4.0 * old, 1.0)

                def neg_r(alpha):
                    h[idx] = alpha
                    return -R_of(h)

                try:
                    res = minimize_scalar(neg_r, bounds=(0.0, hi),
                                          method='bounded',
                                          options={'xatol': 1e-10})
                    cand = res.x
                    cand_r = -res.fun
                except Exception:
                    cand = old
                    cand_r = cur
                if cand_r > cur + 1e-16:
                    h[idx] = cand
                    cur = cand_r
                    improved = True
                else:
                    h[idx] = old
            if not improved:
                break
        return h, cur

    def run_schedule(h0, mu_list, maxiter=2000, maxfun=4000):
        h = _rescale_maxL(h0.copy())
        cur = R_of(h)
        for mu in mu_list:
            if time.process_time() >= deadline:
                break
            try:
                res = minimize(make_pen(mu), h, jac=True, method='L-BFGS-B',
                               bounds=[(0, None)] * h.size,
                               options={'maxiter': maxiter, 'maxfun': maxfun,
                                        'ftol': 1e-15, 'gtol': 1e-12})
                h = _rescale_maxL(res.x)
            except Exception:
                pass
            r = R_of(h)
            if r > cur:
                cur = r
        return h, cur

    def polish(h, cur, do_coord=True):
        if time.process_time() >= deadline:
            return h, cur
        try:
            res = minimize(make_pen(1e9), h, jac=True, method='L-BFGS-B',
                           bounds=[(0, None)] * h.size,
                           options={'maxiter': 3000, 'maxfun': 6000,
                                    'ftol': 1e-15, 'gtol': 1e-12})
            cand = _rescale_maxL(res.x)
            rc = R_of(cand)
            if rc > cur:
                h, cur = cand, rc
        except Exception:
            pass
        if do_coord and time.process_time() < deadline:
            h2, c2 = coord_sweep(h.copy(), cur, 1)
            if c2 > cur:
                h, cur = h2, c2
        return h, cur

    mu_list = [1e0, 3e0, 1e1, 3e1, 1e2, 3e2, 1e3, 3e3, 1e4, 3e4,
               1e5, 3e5, 1e6, 3e6, 1e7, 3e7, 1e8, 3e8, 1e9]

    h, cur = polish(best, bestR, do_coord=False)
    if cur > bestR:
        best, bestR = h.copy(), cur

    while time.process_time() < deadline - 4.0 and best.size < 90000:
        up = _upsample_interp(best, 2)
        hu, cu = run_schedule(up, mu_list, maxiter=1500, maxfun=3000)
        hu, cu = polish(hu, cu, do_coord=False)
        if cu > bestR + 1e-9:
            best, bestR = hu.copy(), cu
            print("pchip-ladder R=%.6f (N=%d)" % (bestR, best.size))
        else:
            if cu > bestR:
                best, bestR = hu.copy(), cu
            print("pchip-ladder no-gain R=%.6f (N=%d)" % (cu, hu.size))
            break

    it = 0
    while time.process_time() < deadline - 1.5:
        it += 1
        h, cur = run_schedule(best, mu_list)
        h, cur = polish(h, cur)
        if cur > bestR + 1e-13:
            best, bestR = h.copy(), cur
            print("iter%d R=%.6f (N=%d)" % (it, bestR, best.size))
        if best.size < 100000 and time.process_time() < deadline - 2.0:
            up = _upsample_interp(best, 2)
            hu, cu = run_schedule(up, mu_list)
            hu, cu = polish(hu, cu)
            if cu > bestR:
                best, bestR = hu.copy(), cu
                print("iter%d up2-pchip R=%.6f (N=%d)" %
                      (it, bestR, best.size))
        if time.process_time() < deadline - 2.0 and best.size < 50000:
            pert = best * (1.0 + 0.02 * rng.standard_normal(best.size))
            pert = np.clip(pert, 0, None)
            if pert.sum() > 0:
                hp, cp = polish(pert, R_of(pert), do_coord=False)
                if cp > bestR:
                    best, bestR = hp.copy(), cp
                    print("iter%d pert R=%.6f (N=%d)" %
                          (it, bestR, best.size))

    # Final aggressive coordinate polish on the best candidate.
    if time.process_time() < deadline:
        h2, c2 = coord_sweep(best.copy(), bestR, 2)
        if c2 > bestR:
            best, bestR = h2, c2
            print("final coord R=%.6f (N=%d)" % (bestR, best.size))

    best = best / best.max()
    print("final R=%.6f (N=%d)" % (bestR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize, minimize_scalar
from scipy.interpolate import PchipInterpolator
from scipy.signal import fftconvolve


