def _R_and_grad(h):
    n = h.size
    s = h.sum()
    if s <= 0:
        return 0.0, np.zeros(n)
    num, dq, s, Lf = _num_and_dq(h)
    am = int(np.argmax(Lf))
    mx = Lf[am]
    den = s * s * mx
    if den <= 0:
        return 0.0, np.zeros(n)
    R = num / den
    coef = num * s * s / (den * den)
    gLf = dq / den
    gLf[am] -= coef
    grad = _backprop(gLf, h)
    grad += -num * 2.0 * s * mx / (den * den)
    return R, grad


def _penalty_and_grad(h, mu):
    n = h.size
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(n)
    num, dq, s, Lf = _num_and_dq(h)
    s2 = s * s
    P = -num / s2
    gLf = -dq / s2
    grad = _backprop(gLf, h)
    grad += 2.0 * num / (s2 * s)
    r = np.maximum(Lf - 1.0, 0.0)
    if np.any(r > 0):
        P += mu * np.sum(r * r)
        grad += _backprop(2.0 * mu * r, h)
    return P, grad


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.75

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = base / base.max()

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.6f (N=%d)" % (bestR, best.size))

    def make_pen(mu):
        def f(x):
            xc = np.clip(x, 0, None)
            P, g = _penalty_and_grad(xc, mu)
            return P, g * (x > 0)
        return f

    def run_pen(h0, mu, maxiter=800, maxfun=1600):
        try:
            res = minimize(make_pen(mu), h0, jac=True, method='L-BFGS-B',
                           bounds=[(0, None)] * h0.size,
                           options={'maxiter': maxiter, 'maxfun': maxfun,
                                    'ftol': 1e-16, 'gtol': 1e-12})
            return _rescale_maxL(res.x)
        except Exception:
            return h0

    def lbfgs_exact(h, maxiter=3000, maxfun=6000):
        def obj(x):
            xc = np.clip(x, 0, None)
            R, g = _R_and_grad(xc)
            return -R, -g * (x > 0)
        try:
            res = minimize(obj, h, jac=True, method='L-BFGS-B',
                           bounds=[(0, None)] * h.size,
                           options={'maxiter': maxiter, 'maxfun': maxfun,
                                    'ftol': 1e-16, 'gtol': 1e-12})
            cand = _rescale_maxL(res.x)
            return cand
        except Exception:
            return h

    mu_list = [1e0, 3e0, 1e1, 3e1, 1e2, 3e2, 1e3, 3e3, 1e4, 3e4,
               1e5, 3e5, 1e6, 3e6, 1e7, 3e7, 1e8, 3e8, 1e9,
               3e9, 1e10, 3e10, 1e11, 3e11, 1e12]

    it = 0
    while time.process_time() < deadline - 1.0:
        it += 1
        h = _rescale_maxL(best.copy())
        cur = bestR
        for mu in mu_list:
            if time.process_time() >= deadline - 1.0:
                break
            h = run_pen(h, mu)
            r = R_of(h)
            if r > cur:
                cur = r
        # polish with exact-gradient ascent
        if time.process_time() < deadline - 1.0:
            h2 = lbfgs_exact(h)
            r2 = R_of(h2)
            if r2 > cur:
                h, cur = h2, r2
        if cur > bestR + 1e-13:
            best, bestR = h.copy(), cur
            print("iter%d R=%.6f (N=%d)" % (it, bestR, best.size))
        else:
            # try exact ascent directly from best to escape plateau
            h2 = lbfgs_exact(best.copy())
            r2 = R_of(h2)
            if r2 > bestR + 1e-13:
                best, bestR = h2, r2
                print("exact R=%.6f (N=%d)" % (bestR, best.size))
            else:
                break

    # Final exact polishing passes until time runs low.
    while time.process_time() < deadline - 0.3:
        h2 = lbfgs_exact(best.copy(), maxiter=1000, maxfun=2000)
        r2 = R_of(h2)
        if r2 > bestR + 1e-14:
            best, bestR = h2, r2
            print("polish R=%.6f (N=%d)" % (bestR, best.size))
        else:
            break

    print("final R=%.6f (N=%d)" % (bestR, best.size))
    return best

