    dq[1:] += (a + 2*b)
    dq /= 3.0
    return num, dq, h.sum(), Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _penalty_and_grad(h, mu):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, s, Lf = _num_and_dq(h)
    s2 = s * s
    P = -num / s2
    gLf = -dq / s2
    grad = _backprop(gLf, h)
    grad += 2.0 * num / (s2 * s)
    r = np.maximum(Lf - 1.0, 0.0)
    if np.any(r > 0):
        P += mu * np.sum(r * r)
        w = 2.0 * mu * r
        grad += _backprop(w, h)
    return P, grad


def _pnorm_and_grad(h, p):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, s, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return 1e18, np.zeros(h.size)
    u = Lf / mx
    up = u ** p
    S = np.sum(up)
    if S <= 0:
        return 1e18, np.zeros(h.size)
    M = mx * S ** (1.0 / p)
    s2 = s * s
    P = -num / (s2 * M)
    # dP/dLf = -num/s2 * d(1/M)/dLf = (num/s2) * (1/M^2) * dM/dLf
    # dM/dLf = M^(1-p) * Lf^(p-1)
    coef = num / (s2 * M * M)
    dM = np.zeros_like(Lf)
    nz = Lf > 0
    dM[nz] = (M ** (1 - p)) * (Lf[nz] ** (p - 1))
    gLf = coef * dM
    # num term gradient
    gLf = gLf - dq / (s2 * M)
    grad = _backprop(gLf, h)
    grad += 2.0 * num / (s2 * s * M)
    return P, grad


