    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    num = np.sum(L[:-1]**2 + L[:-1]*L[1:] + L[1:]**2) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2*a + b)
    dq[1:] += (a + 2*b)
    dq /= 3.0
    return num, dq, h.sum(), Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _R_and_grad(h):
    n = h.size
    s = h.sum()
    if s <= 0:
        return 0.0, np.zeros(n)
    num, dq, s, Lf = _num_and_dq(h)
    am = int(np.argmax(Lf))
    mx = Lf[am]
    den = s * s * mx
    if den <= 0:
        return 0.0, np.zeros(n)
    R = num / den
    coef = num * s * s / (den * den)
    gLf = dq / den
    gLf[am] -= coef
    grad = _backprop(gLf, h)
    ds = -num * 2.0 * s * mx / (den * den)
    grad += ds
    return R, grad


def _penalty_and_grad(h, mu):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, s, Lf = _num_and_dq(h)
    s2 = s * s
    P = -num / s2
    gLf = -dq / s2
    grad = _backprop(gLf, h)
    grad += 2.0 * num / (s2 * s)
    r = np.maximum(Lf - 1.0, 0.0)
    if np.any(r > 0):
        P += mu * np.sum(r * r)
        w = 2.0 * mu * r
        grad += _backprop(w, h)
    return P, grad


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.asarray(start, dtype=float).copy()
        base = np.clip(base, 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = base / base.max()

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.6f (N=%d)" % (bestR, best.size))

    def make_pen(mu):
        def f(x):
            xc = np.clip(x, 0, None)
            P, g = _penalty_and_grad(xc, mu)
            g = g * (x > 0)
            return P, g
        return f

    def run_pen(h0, mu, maxiter, maxfun):
        try:
            res = minimize(make_pen(mu), h0, jac=True, method='L-BFGS-B',
                           bounds=[(0, None)] * h0.size,
                           options={'maxiter': maxiter, 'maxfun': maxfun,
                                    'ftol': 1e-16, 'gtol': 1e-12})
            return _rescale_maxL(res.x)
        except Exception:
            return h0

    def stage_budget(mu):
        if mu <= 1e2:
            return 80, 160
        if mu <= 1e7:
            return 200, 400
        return 500, 1000

    mu_list = [1e0, 3e0, 1e1, 3e1, 1e2, 3e2, 1e3, 3e3, 1e4, 3e4,
               1e5, 3e5, 1e6, 3e6, 1e7, 3e7, 1e8, 3e8, 1e9,
               3e9, 1e10, 3e10, 1e11, 3e11, 1e12, 3e12, 1e13]

    def exact_obj(x):
        xc = np.clip(x, 0, None)
        R, g = _R_and_grad(xc)
        g = g * (x > 0)
        return -R, -g

    def lbfgs_exact(h):
        try:
            res = minimize(exact_obj, h, jac=True, method='L-BFGS-B',
                           bounds=[(0, None)] * h.size,
                           options={'maxiter': 4000, 'maxfun': 8000,
                                    'ftol': 1e-15, 'gtol': 1e-12})
            cand = np.clip(res.x, 0, None)
            if cand.sum() > 0:
                cand = cand / cand.max()
                return cand, R_of(cand)
        except Exception:
            pass
        return h, R_of(h)

    # First: polish the start with a full penalty schedule.
    h = _rescale_maxL(best.copy())
    cur = bestR
    for mu in mu_list:
        if time.process_time() >= deadline - 0.5:
            break
        mi, mf = stage_budget(mu)
        h = run_pen(h, mu, mi, mf)
        r = R_of(h)
        if r > cur:
            cur = r
    if cur > bestR:
        best, bestR = h.copy(), cur
        print("schedule R=%.6f (N=%d)" % (bestR, best.size))

    # Exact-gradient L-BFGS polish.
    if time.process_time() < deadline - 1.0:
        h2, r2 = lbfgs_exact(best.copy())
        if r2 > bestR:
            best, bestR = h2.copy(), r2
            print("exact-lbfgs R=%.6f (N=%d)" % (bestR, best.size))

    # SPSA-like random-direction descent on the full vector.
    rng = np.random.default_rng(777)
    h = best.copy()
    cur = bestR
    n = h.size
    step = 1e-3 * max(h.max(), 1e-9)
    while time.process_time() < deadline - 0.4:
        d = rng.standard_normal(n)
        d -= d.mean()
        improved = False
        for sgn in (1.0, -1.0):
            htry = np.clip(h + sgn * step * d, 0, None)
            htry = _rescale_maxL(htry)
            r = R_of(htry)
            if r > cur + 1e-14:
                h, cur = htry, r
                improved = True
                break
        if not improved:
            step *= 0.85
            if step < 1e-9 * max(h.max(), 1e-9):
                break
        else:
            step *= 1.02

    if cur > bestR:
        best, bestR = h.copy(), cur
        print("spsa R=%.6f (N=%d)" % (bestR, best.size))

    # Final exact polish.
    if time.process_time() < deadline - 0.3:
        h2, r2 = lbfgs_exact(best.copy())
        if r2 > bestR:
            best, bestR = h2.copy(), r2

    best = best / max(best.max(), 1e-300)
    print("final R=%.6f (N=%d)" % (bestR, best.size))
    return best

