                       bounds=[(0, None)] * h0.size,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': ftol, 'gtol': gtol})
        return _rescale_maxL(res.x)
    except Exception:
        return h0


def _mu_ladder():
    mu_list = []
    m = 1.0
    while m < 3e12:
        mu_list.append(m)
        mu_list.append(3.0 * m)
        m *= 10.0
    return mu_list


def _stage_budget(mu):
    if mu < 1e3:
        return 300, 600
    if mu < 1e8:
        return 500, 1000
    return 1200, 2400


def _coarsen(h, factor):
    n = h.size
    m = n // factor
    if m < 1:
        return h.copy()
    hc = h[:m * factor].reshape(m, factor).sum(axis=1)
    return hc


def _refine(hc, target_n):
    m = hc.size
    xs = np.linspace(0.0, 1.0, m)
    xt = np.linspace(0.0, 1.0, target_n)
    f = PchipInterpolator(xs, hc, extrapolate=False)
    out = f(xt)
    out = np.nan_to_num(out, nan=0.0, posinf=0.0, neginf=0.0)
    return np.clip(out, 0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.88

