import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    num = np.sum(L[:-1]**2 + L[:-1]*L[1:] + L[1:]**2) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2*a + b)
    dq[1:] += (a + 2*b)
    dq /= 3.0
    return num, dq, h.sum(), Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _penalty_and_grad(h, mu):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, s, Lf = _num_and_dq(h)
    s2 = s * s
    P = -num / s2
    gLf = -dq / s2
    grad = _backprop(gLf, h)
    grad += 2.0 * num / (s2 * s)
    r = np.maximum(Lf - 1.0, 0.0)
    if np.any(r > 0):
        P += mu * np.sum(r * r)
        w = 2.0 * mu * r
        grad += _backprop(w, h)
    return P, grad


def _R_and_grad(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    n = h.size
    if s <= 0:
        return 0.0, np.zeros(n)
    num, dq, s, Lf = _num_and_dq(h)
    s2 = s * s
    mx = Lf.max()
    if mx <= 0:
        return 0.0, np.zeros(n)
    R = (num / s2) / mx
    g_num = _backprop(dq / s2, h)
    g_num += -2.0 * num / (s2 * s)
    k = int(np.argmax(Lf))
    dmx = np.zeros(n)
    j = k - 1
    lo = max(0, j - (n - 1))
    hi = min(n - 1, j)
    if lo <= hi:
        idx = np.arange(lo, hi + 1)
        dmx[idx] = 2.0 * h[j - idx]
    grad = (g_num * mx - (num / s2) * dmx) / (mx * mx)
    return R, grad


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _upsample(h, factor):
    """Linear-interpolation refinement: split each step into `factor` steps."""
    n = h.size
    if factor <= 1:
        return h.copy()
    # treat h as piecewise-constant; resample to factor*n by averaging over subcells
    # Use simple nearest-neighbour / linear blend: keep plateau, then slight smoothing.
    idx = np.arange(n * factor) / factor
    i0 = np.floor(idx).astype(int)
    i0 = np.clip(i0, 0, n - 1)
    return h[i0].astype(float)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.80

    if start is not None:
        base = np.asarray(start, dtype=float).copy()
        base = np.clip(base, 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = base / base.max()

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.6f (N=%d)" % (bestR, best.size))

    def make_pen(mu):
        def f(x):
            xc = np.clip(x, 0, None)
            P, g = _penalty_and_grad(xc, mu)
            g = g * (x > 0)
            return P, g
        return f

    def run_pen(h0, mu, maxiter, maxfun):
        try:
            res = minimize(make_pen(mu), h0, jac=True, method='L-BFGS-B',
                           bounds=[(0, None)] * h0.size,
                           options={'maxiter': maxiter, 'maxfun': maxfun,
                                    'ftol': 1e-16, 'gtol': 1e-12})
            return _rescale_maxL(res.x)
        except Exception:
            return h0

    def run_exact(h0, maxiter=200, maxfun=400):
        def f(x):
            xc = np.clip(x, 0, None)
            R, g = _R_and_grad(xc)
            g = g * (x > 0)
            return -R, -g
        try:
            res = minimize(f, h0, jac=True, method='L-BFGS-B',
                           bounds=[(0, None)] * h0.size,
                           options={'maxiter': maxiter, 'maxfun': maxfun,
                                    'ftol': 1e-16, 'gtol': 1e-12})
            return _rescale_maxL(res.x)
        except Exception:
            return h0

    def stage_budget(mu):
        if mu <= 1e2:
            return 80, 160
        if mu <= 1e7:
            return 200, 400
        return 500, 1000

    mu_list = [1e0, 3e0, 1e1, 3e1, 1e2, 3e2, 1e3, 3e3, 1e4, 3e4,
               1e5, 3e5, 1e6, 3e6, 1e7, 3e7, 1e8, 3e8, 1e9,
               3e9, 1e10, 3e10, 1e11, 3e11, 1e12]

    # Phase A: refine at current resolution.
    it = 0
    while time.process_time() < deadline - 0.5:
        it += 1
        h = _rescale_maxL(best.copy())
        cur = bestR
        improved_pass = False
        for mu in mu_list:
            if time.process_time() >= deadline - 0.5:
                break
            mi, mf = stage_budget(mu)
            h = run_pen(h, mu, mi, mf)
            r = R_of(h)
            if r > cur:
                cur = r
            if time.process_time() > deadline - 2.0:
                break
        if cur > bestR + 1e-13:
            best, bestR = h.copy(), cur
            improved_pass = True
            print("iter%d R=%.6f (N=%d)" % (it, bestR, best.size))
            if time.process_time() < deadline - 1.0:
                h3 = run_exact(_rescale_maxL(best.copy()))
                r3 = R_of(h3)
                if r3 > bestR + 1e-13:
                    best, bestR = h3.copy(), r3
                    print("exact R=%.6f (N=%d)" % (bestR, best.size))
        if not improved_pass:
            break

    # Phase B: upsample (refine resolution) and polish if budget remains.
    # Only do a small factor to avoid blowing up cost.
    for factor in (2, 2):
        if time.process_time() > deadline - 3.0:
            break
        newN = best.size * factor
        if newN > 200000:
            break
        h_up = _upsample(best, factor)
        r_up = R_of(h_up)
        # Polish at new resolution using a short schedule
        hpol = _rescale_maxL(h_up)
        cur = r_up
        for mu in [1e6, 1e8, 1e10, 1e11, 1e12]:
            if time.process_time() > deadline - 2.5:
                break
            hpol = run_pen(hpol, mu, 400, 800)
            r = R_of(hpol)
            if r > cur:
                cur = r
        if time.process_time() < deadline - 1.5:
            h3 = run_exact(_rescale_maxL(hpol), maxiter=150, maxfun=300)
            r3 = R_of(h3)
            if r3 > cur:
                hpol, cur = h3, r3
        if cur > bestR + 1e-13:
            best, bestR = hpol.copy(), cur
            print("up x%d R=%.6f (N=%d)" % (factor, bestR, best.size))

    print("final R=%.6f (N=%d)" % (bestR, best.size))
    return best

