            num, dq, Lf = _num_and_dq(xc)
            if num <= 0:
                return 1e18, np.zeros(xc.size)
            M = Lf.max()
            z = beta * (Lf - M)
            e = np.exp(z)
            Z = e.sum()
            logM = M + np.log(Z) / beta
            P = -np.log(num) + 2.0 * np.log(s) + logM
            gLf = -dq / num + e / Z
            grad = _backprop(gLf, xc)
            grad += 2.0 / s
