    else:
        base = np.ones(50)
    base = base / base.max()

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.6f (N=%d)" % (bestR, best.size))

    def make_pen(mu):
        def f(x):
            xc = np.clip(x, 0, None)
            P, g = _penalty_and_grad(xc, mu)
            return P, g * (x > 0)
        return f

    def run_pen(h0, mu, maxiter, maxfun, ftol=1e-16, gtol=1e-12):
        if time.process_time() >= deadline - 1.5:
            return h0
        try:
            res = minimize(make_pen(mu), h0, jac=True, method='L-BFGS-B',
                           bounds=[(0, None)] * h0.size,
                           options={'maxiter': maxiter, 'maxfun': maxfun,
                                    'ftol': ftol, 'gtol': gtol})
            return _rescale_maxL(res.x)
        except Exception:
            return h0

    mu_list = []
    m = 1.0
    while m < 3e12:
        mu_list.append(m)
        mu_list.append(3.0 * m)
        m *= 10.0

    def stage_budget(mu):
        if mu < 1e3:
            return 300, 600
        if mu < 1e8:
            return 500, 1000
        return 1200, 2400

    # Phase 1: penalty ladder refinement from start.
    h = _rescale_maxL(best.copy())
    cur = bestR
    for mu in mu_list:
        if time.process_time() >= deadline - 1.5:
            break
        mi, mf = stage_budget(mu)
        h = run_pen(h, mu, mi, mf)
        r = R_of(h)
        if r > cur:
            cur = r
    if cur > bestR + 1e-13:
        best, bestR = h.copy(), cur
        print("pen R=%.6f (N=%d)" % (bestR, best.size))

    # Phase 2: direct logsumexp polishing with beta ladder, repeated
    # until time runs out.  Each pass restarts from the best so far.
    beta_ladder = [50.0, 200.0, 800.0, 3000.0, 12000.0, 50000.0]
    it = 0
    while time.process_time() < deadline - 1.5:
        it += 1
        start_R = bestR
        h = _rescale_maxL(best.copy())
        for b in beta_ladder:
            if time.process_time() >= deadline - 1.5:
                break
            h = run_direct(h, b, 600, 1200, deadline)
            r = R_of(h)
            if r > bestR + 1e-14:
                best, bestR = h.copy(), r
        if bestR - start_R < 5e-12:
            break

    # Phase 3: micro penalty polish at very high mu to squeeze out residual.
    while time.process_time() < deadline - 1.5:
        start_R = bestR
        h = _rescale_maxL(best.copy())
        for mu in [1e12, 1e13, 1e14, 1e15]:
            if time.process_time() >= deadline - 1.5:
                break
            h = run_pen(h, mu, 1500, 3000)
            r = R_of(h)
            if r > bestR + 1e-14:
                best, bestR = h.copy(), r
        if bestR - start_R < 5e-12:
            break

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _convolve(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _convolve(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    L = _convolve(h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2*a + b)
    dq[1:] += (a + 2*b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _penalty_and_grad(h, mu):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    s2 = s * s
    P = -num / s2
    gLf = -dq / s2
    grad = _backprop(gLf, h)
    grad += 2.0 * num / (s2 * s)
    r = np.maximum(Lf - 1.0, 0.0)
    if np.any(r > 0):
        P += mu * np.sum(r * r)
        grad += _backprop(2.0 * mu * r, h)
    return P, grad


# Soft-max direct objective (smooths the max of L).
def _soft_obj_grad(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    logM = mx + np.log(Z) / beta
    w = e / Z
    obj = -np.log(num) + 2.0 * np.log(s) + logM
    gLf = -dq / num + w
    grad = _backprop(gLf, h)
    grad += 2.0 / s
    return obj, grad


def _upsample(h, f):
    h = np.asarray(h, dtype=float)
    n = h.size
    xf = (np.arange(n * f) + 0.5) / f - 0.5
    out = np.interp(xf, np.arange(n), h)
    out = np.clip(out, 0, None)
    m = out.max()
    if m > 0:
        out = out / m
    return out


def _polish_direct(h, beta, deadline, maxiter=600, maxfun=1200):
    if time.process_time() >= deadline - 1.0:
        return h
    def f(x):
        xc = np.clip(x, 0, None)
        o, g = _soft_obj_grad(xc, beta)
        return o, g * (x > 0)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0, None)] * h.size,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-17, 'gtol': 1e-13})
        return _rescale_maxL(res.x)
    except Exception:
        return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = base / base.max()

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.6f (N=%d)" % (bestR, best.size))

    def make_pen(mu):
        def f(x):
            xc = np.clip(x, 0, None)
            P, g = _penalty_and_grad(xc, mu)
            return P, g * (x > 0)
        return f

    def run_pen(h0, mu, maxiter=800, maxfun=1600):
        if time.process_time() >= deadline - 1.0:
            return h0
        try:
            res = minimize(make_pen(mu), h0, jac=True, method='L-BFGS-B',
                           bounds=[(0, None)] * h0.size,
                           options={'maxiter': maxiter, 'maxfun': maxfun,
                                    'ftol': 1e-16, 'gtol': 1e-12})
            return _rescale_maxL(res.x)
        except Exception:
            return h0

    mu_list = []
    m = 1.0
    while m < 1e14:
        mu_list.append(m)
        mu_list.append(3.0 * m)
        m *= 10.0

    def schedule(h0):
        h = _rescale_maxL(h0.copy())
        cur = R_of(h)
        for mu in mu_list:
            if time.process_time() >= deadline - 1.0:
                break
            h = run_pen(h, mu)
            r = R_of(h)
            if r > cur:
                cur = r
        return h, cur

    def polish(h, cur):
        if time.process_time() < deadline - 1.0:
            h2 = _polish_direct(h, 200, deadline)
            r2 = R_of(h2)
            if r2 > cur:
                h, cur = h2, r2
        if time.process_time() < deadline - 1.0:
            h3 = _polish_direct(h, 2000, deadline, 400, 800)
            r3 = R_of(h3)
            if r3 > cur:
                h, cur = h3, r3
        return h, cur

    # First: polish the start at its own resolution.
    h, cur = schedule(best)
    h, cur = polish(h, cur)
    if cur > bestR:
        best, bestR = h.copy(), cur
        print("after own-res polish R=%.6f (N=%d)" % (bestR, best.size))

    # Then progressively upsample and refine.
    it = 0
    while time.process_time() < deadline - 2.0 and best.size < 200000:
        it += 1
        if best.size < 100000:
            up = _upsample(best, 2)
        else:
            up = best.copy()
        hu, cu = schedule(up)
        hu, cu = polish(hu, cu)
        if cu > bestR + 1e-13:
            best, bestR = hu.copy(), cu
            print("iter%d R=%.6f (N=%d)" % (it, bestR, best.size))
        else:
            # No gain from upsampling; keep polishing current best.
            hb, cb = polish(best.copy(), bestR)
            if cb > bestR + 1e-13:
                best, bestR = hb, cb
                print("iter%d polish R=%.6f (N=%d)" % (it, bestR, best.size))
            if best.size >= 100000:
                break

    # Final tightening at current resolution.
    if time.process_time() < deadline - 1.0:
        hb, cb = polish(best.copy(), bestR)
        if cb > bestR:
            best, bestR = hb, cb

    best = best / best.max()
    print("final R=%.6f (N=%d)" % (bestR, best.size))
    return best

