def _cascade_field(n, rng):
    u = np.zeros(n)
    l = 0
    while (1 << l) <= n and l <= 11:
        blk = 1 << l
        nb = (n + blk - 1) // blk
        vals = rng.standard_normal(nb) * (0.03 * (2.0 ** (-0.5 * l)))
        u += np.repeat(vals, blk)[:n]
