def _resample(h, n_new):
    n = h.size
    if n == n_new:
        return h.copy()
    xi = np.linspace(0.0, n, n_new + 1)
    xj = np.arange(n + 1)
    return np.interp(xi[:-1] + 0.5, xj, np.concatenate((h, [0.0])))


def _finer(h, n_new):
