                continue
            h2 = _finer(h, n2)
            h2 = _rescale_maxL(h2)
            for mu in (1e12, 1e13, 3e13):
                if time.process_time() >= deadline - 1.5:
                    break
                h2 = run_pen(h2, mu, 400, 800, ftol=1e-18, gtol=1e-14)
            h2, r2 = active_polish(h2, R_of(h2), beta=2000.0, iters=400)
            if r2 > cur + 1e-12:
                print("finer R=%.6f (N=%d)" % (r2, h2.size))
                return h2, r2
        return h, cur

    it = 0
    while time.process_time() < deadline - 1.0:
        it += 1
        h = _rescale_maxL(best.copy())
        cur = bestR
        for mu in mu_list:
            if time.process_time() >= deadline - 1.0:
                break
            mi, mf = stage_budget(mu)
            h = run_pen(h, mu, mi, mf)
            r = R_of(h)
            if r > cur:
                cur = r
        if cur > bestR + 1e-13:
            h, cur = direct_polish(h, cur)
        # active-support direct polish
        h, cur = active_polish(h, cur, beta=2000.0, iters=1000)
        if cur > bestR + 1e-13:
            best, bestR = h.copy(), cur
            print("iter%d R=%.6f (N=%d)" % (it, bestR, best.size))
        else:
            polished_any = False
            while time.process_time() < deadline - 1.0:
                h2 = _rescale_maxL(best.copy())
                cur2 = bestR
                for mu in polish_list:
                    if time.process_time() > deadline - 1.5:
                        break
                    if mu >= 1e13:
                        h2 = run_pen(h2, mu, 2000, 4000,
                                     ftol=1e-20, gtol=1e-16)
                    else:
                        h2 = run_pen(h2, mu, 1500, 3000,
                                     ftol=1e-18, gtol=1e-14)
