                gain = cur2 - bestR
                if cur2 > bestR + 1e-13:
                    best, bestR = h2.copy(), cur2
                    polished_any = True
                    print("polish R=%.6f (N=%d)" % (bestR, best.size))
                if gain < 1e-10:
                    break
            if polished_any:
                continue

            # ---- Try finer discretization ----
            h2, r2 = try_finer(best, bestR)
            if r2 > bestR + 1e-12:
                best, bestR = h2, r2
                print("finer-improve R=%.6f (N=%d)" % (bestR, best.size))
                continue

            # ---- random support perturbation + active re-opt ----
            rng = np.random.default_rng(it + 1000)
            improved = False
            for _ in range(4):
                if time.process_time() >= deadline - 1.5:
                    break
                h2 = best.copy()
                nz = h2 > 1e-9 * h2.max()
                if np.any(nz):
                    h2[nz] *= (1.0 + 1e-3 * rng.standard_normal(nz.sum()))
                h2 = _rescale_maxL(np.clip(h2, 0, None))
                for mu in (1e12, 1e13, 3e13):
                    if time.process_time() >= deadline - 1.5:
                        break
                    h2 = run_pen(h2, mu, 400, 800, ftol=1e-18, gtol=1e-14)
                h2, r2 = active_polish(h2, R_of(h2), beta=2000.0, iters=600)
                if r2 > bestR + 1e-12:
                    best, bestR = h2, r2
                    print("perturb%d R=%.6f (N=%d)" % (it, bestR, best.size))
                    improved = True
                    break
            if improved:
                continue
            break

    print("final R=%.6f (N=%d)" % (bestR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2*a + b)
    dq[1:] += (a + 2*b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _direct_obj_grad(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    e = np.exp(np.clip(beta * (Lf - mx), -50, 0))
    Z = e.sum()
    logM = mx + np.log(Z) / beta
    w = e / Z
    obj = -np.log(num) + 2.0 * np.log(s) + logM
    gLf = -dq / num + w
    grad = _backprop(gLf, h)
    grad += 2.0 / s
    return obj, grad


def run_direct(h0, beta, maxiter, maxfun, deadline):
    if time.process_time() >= deadline - 1.0:
        return h0
    def f(x):
        xc = np.clip(x, 0, None)
        o, g = _direct_obj_grad(xc, beta)
        return o, g * (x > 0)
    try:
        res = minimize(f, h0, jac=True, method='L-BFGS-B',
                       bounds=[(0, None)] * h0.size,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-17, 'gtol': 1e-13})
        return _rescale_maxL(res.x)
    except Exception:
        return h0


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.6f (N=%d)" % (bestR, best.size))

    # --- Main change: use the direct log-sum-exp objective (which handles the
    # max smoothly and jointly with num/s) as the *primary* optimizer, with a
    # continuation in beta.  This directly targets R without the two-stage
    # penalty/feasibility dance that tends to stall. ---
    betas = [20, 50, 100, 200, 400, 800, 1600, 3200]
    for beta in betas:
        if time.process_time() >= deadline - 1.5:
            break
        h = run_direct(best, beta, 800, 1600, deadline)
        r = R_of(h)
        if r > bestR + 1e-14:
            best, bestR = h.copy(), r
            print("beta%d R=%.7f" % (beta, bestR))

    # --- Fine polish: aggressive high-beta runs on the current best. ---
    for beta in (6400, 12800, 25600):
        if time.process_time() >= deadline - 1.5:
            break
        h = run_direct(best, beta, 1500, 3000, deadline)
        r = R_of(h)
        if r > bestR + 1e-14:
            best, bestR = h.copy(), r
            print("polish b%d R=%.7f" % (beta, bestR))

    # --- Multigrid refinement: coarsen, optimize, upsample, refine. ---
    def vcycle(h, cur):
        n = h.size
        if n % 2 != 0 or n < 8:
            return h, cur
        h_c = 0.5 * (h[0::2] + h[1::2])
        h_c = _rescale_maxL(h_c)
        for beta in (200, 800, 3200):
            if time.process_time() >= deadline - 1.0:
                return h, cur
            h_c = run_direct(h_c, beta, 400, 800, deadline)
        up = np.zeros(n)
        up[0::2] = h_c
        up[1::2] = h_c
        up[-1] = h_c[-1]
        h_up = _rescale_maxL(up)
        for beta in (800, 3200, 12800):
            if time.process_time() >= deadline - 1.0:
                return h, cur
            h_up = run_direct(h_up, beta, 600, 1200, deadline)
        r = R_of(h_up)
        if r > cur + 1e-14:
            return h_up, r
        return h, cur

    if time.process_time() < deadline - 2.0:
        h, cur = vcycle(best, bestR)
        if cur > bestR + 1e-14:
            best, bestR = h, cur
            print("vcycle R=%.7f (N=%d)" % (bestR, best.size))

    # --- Final high-beta squeeze. ---
    for beta in (25600, 51200, 102400):
        if time.process_time() >= deadline - 1.0:
            break
        h = run_direct(best, beta, 2000, 4000, deadline)
        r = R_of(h)
        if r > bestR + 1e-14:
            best, bestR = h.copy(), r
            print("final b%d R=%.7f" % (beta, bestR))

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

