    except Exception:
        return h0


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90
    margin = 1.5

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = base / base.max()

    best = _rescale_maxL(base.copy())
    bestR = R_of(best)
    print("start R=%.6f (N=%d)" % (bestR, best.size))

    # ---- Local coordinate refinement: perturb individual heights & accept ----
    # This is cheap and can nudge a plateau into a slightly better shape.
    rng = np.random.RandomState(12345)

    def local_polish(h, cur, iters, deadline):
        n = h.size
        step = 0.02
        for _ in range(iters):
            if time.process_time() >= deadline:
                break
            idx = rng.randint(0, n, size=max(1, n // 200))
            trial = h.copy()
            trial[idx] = np.maximum(trial[idx] * (1.0 + step * rng.randn(idx.size)), 0.0)
            trial = _rescale_maxL(trial)
            r = R_of(trial)
            if r > cur:
                h, cur = trial, r
        return h, cur

    # ---- Direct-R polishing with increasing beta schedule ----
    def direct_polish(h, cur, deadline):
        for beta in (100.0, 300.0, 1000.0, 3000.0, 10000.0):
            if time.process_time() >= deadline:
                break
            h2 = _run_direct(h, beta, 500, 1000, deadline)
            r2 = R_of(h2)
            if r2 > cur + 1e-14:
                h, cur = h2, r2
        return h, cur

    # ---- Iterate: alternate direct polish and local coordinate polish ----
    it = 0
    stall = 0
    while time.process_time() < deadline - margin:
        it += 1
        prevR = bestR

        h, cur = direct_polish(best.copy(), bestR, deadline - margin)
        if cur > bestR + 1e-14:
            best, bestR = h, cur

        h, cur = local_polish(best.copy(), bestR,
                              iters=200, deadline=deadline - margin)
        if cur > bestR + 1e-14:
            best, bestR = h, cur

        if bestR > prevR + 1e-13:
            stall = 0
            print("iter%d R=%.7f (N=%d)" % (it, bestR, best.size))
        else:
            stall += 1
            if stall >= 3:
                break

    # ---- Final direct push with remaining budget ----
    while time.process_time() < deadline - margin:
        h2 = _run_direct(best.copy(), 30000.0, 800, 1600, deadline - margin)
        r2 = R_of(h2)
        if r2 > bestR + 1e-14:
            best, bestR = h2, r2
            print("final push R=%.7f" % bestR)
        else:
            break

    print("final R=%.6f (N=%d)" % (bestR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1200:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1200:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1200:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _R_and_grad(h):
    n = h.size
    s = h.sum()
    if s <= 0:
        return 0.0, np.zeros(n)
    num, dq, Lf = _num_and_dq(h)
    am = int(np.argmax(Lf))
    mx = Lf[am]
    den = s * s * mx
    if den <= 0:
        return 0.0, np.zeros(n)
    R = num / den
    coef = num * s * s / (den * den)
    gLf = dq / den
    gLf[am] -= coef
    grad = _backprop(gLf, h)
    grad += -num * 2.0 * s * mx / (den * den)
    return R, grad


def _direct_obj_grad(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    e = np.exp(np.clip(beta * (Lf - mx), -50, 0))
    Z = e.sum()
    logM = mx + np.log(Z) / beta
    w = e / Z
    obj = -np.log(num) + 2.0 * np.log(s) + logM
    gLf = -dq / num + w
    grad = _backprop(gLf, h)
    grad += 2.0 / s
    return obj, grad


def run_direct(h0, beta, maxiter, maxfun, deadline):
    if time.process_time() >= deadline - 1.0:
        return h0
    def f(x):
        xc = np.clip(x, 0, None)
        o, g = _direct_obj_grad(xc, beta)
        return o, g * (x > 0)
    try:
        res = minimize(f, h0, jac=True, method='L-BFGS-B',
                       bounds=[(0, None)] * h0.size,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-17, 'gtol': 1e-13})
        return _rescale_maxL(res.x)
    except Exception:
        return h0


def run_masked(h0, free, beta, maxiter, maxfun, deadline):
    if time.process_time() >= deadline - 1.0:
        return h0
    mask = free.astype(float)
    def f(x):
        xc = np.clip(x, 0, None)
        o, g = _direct_obj_grad(xc, beta)
        return o, g * mask * (x > 0)
    try:
        res = minimize(f, h0, jac=True, method='L-BFGS-B',
                       bounds=[(0, None)] * h0.size,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-17, 'gtol': 1e-13})
        return _rescale_maxL(res.x)
    except Exception:
        return h0


def _free_set(h, nfree_cap=6000):
    n = h.size
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    free = np.zeros(n, dtype=bool)
    k = min(24, n)
    top = np.argpartition(h, -k)[-k:]
    for idx in top:
        lo = max(0, idx - 80); hi = min(n, idx + 81)
        free[lo:hi] = True
    lo_r = m - n + 1
    a_lo = max(0, lo_r); a_hi = min(n - 1, lo_r + 250)
    if a_hi >= a_lo:
        free[a_lo:a_hi + 1] = True
    b_lo = max(0, m - 250); b_hi = min(n - 1, m)
    if b_hi >= b_lo:
        free[b_lo:b_hi + 1] = True
    gLf = -dq / num
    gLf[m] += 1.0
    grad = _backprop(gLf, h)
    kk = min(3000, n)
    topg = np.argpartition(np.abs(grad), -kk)[-kk:]
    free[topg] = True
    idxs = np.nonzero(free)[0]
    if idxs.size > nfree_cap:
        sel = idxs[np.argpartition(np.abs(grad[idxs]), -nfree_cap)[-nfree_cap:]]
        free[:] = False
        free[sel] = True
    return free


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.88

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.6f (N=%d)" % (bestR, best.size))

    def try_update(h):
        nonlocal best, bestR
        if h.size == 0 or h.sum() <= 0:
            return False
        r = R_of(h)
        if r > bestR + 1e-13:
            best, bestR = h.copy(), r
            return True
        return False

    # Main change: ZOH-doubling to escape discretisation, then restricted polish.
    h2 = np.repeat(best, 2)
    h2 = _rescale_maxL(h2)
    r2 = R_of(h2)
    print("doubled R=%.9f vs %.9f (N=%d)" % (r2, bestR, h2.size))
    if r2 > bestR + 1e-13:
        best, bestR = h2, r2

    # Exact full polish on the doubled representation.
    h = run_direct(best, 1e6, 800, 1600, deadline)
    if try_update(h):
        print("direct R=%.6f (N=%d)" % (bestR, best.size))

    # Restricted-mask polish over a beta continuation.
    betas = (300, 2000, 10000, 50000)
    cur = best.copy()
    while time.process_time() < deadline - 1.5:
        free = _free_set(cur)
        for beta in betas:
            if time.process_time() >= deadline - 1.0:
                break
            cur = run_masked(cur, free, beta, 400, 800, deadline)
            if try_update(cur):
                print("mask beta=%g R=%.6f (N=%d)" % (beta, bestR, best.size))
        # Refresh free set from the best so far.
        if not np.array_equal(cur, best):
            cur = best.copy()
        else:
            break

    # Final stiff-mu continuation in logM form, on the best.
    h = best.copy()
    for beta in (1e5, 1e6, 1e7, 1e8):
        if time.process_time() >= deadline - 0.5:
            break
        h = run_direct(h, beta, 300, 600, deadline)
        if try_update(h):
            print("stiff beta=%g R=%.6f (N=%d)" % (beta, bestR, best.size))

    best = best / best.max()
    print("final R=%.6f (N=%d)" % (bestR, best.size))
    return best

