import time
from scipy.optimize import minimize, minimize_scalar
from scipy.signal import fftconvolve


def _conv(a, b):
    if a.size > 1500:
        return fftconvolve(a, b)
    return np.convolve(a, b)


def _knots(h):
    L = _conv(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    L = _conv(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2*a + b)
    dq[1:] += (a + 2*b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _R_and_grad(h):
    n = h.size
    s = h.sum()
    if s <= 0:
        return 0.0, np.zeros(n)
    num, dq, Lf = _num_and_dq(h)
    am = int(np.argmax(Lf))
    mx = Lf[am]
    den = s * s * mx
    if den <= 0:
        return 0.0, np.zeros(n)
    R = num / den
    coef = num * s * s / (den * den)
    gLf = dq / den
    gLf[am] -= coef
    grad = _backprop(gLf, h)
    grad += -num * 2.0 * s * mx / (den * den)
    return R, grad


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _upsample_interp(h, f):
    h = np.asarray(h, dtype=float)
    n = h.size
    xf = (np.arange(n * f) + 0.5) / f - 0.5
    out = np.interp(xf, np.arange(n), h)
    out = np.clip(out, 0, None)
    m = out.max()
    if m > 0:
        out = out / m
    return out


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85
    rng = np.random.default_rng(12345)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.6f (N=%d)" % (bestR, best.size))

    def lb_opt(h, maxiter, maxfun, deadline_inner=None):
        if deadline_inner is None:
            deadline_inner = deadline
        if time.process_time() >= deadline_inner - 0.1:
            return h
        def f(x):
            xc = np.clip(x, 0, None)
            R, g = _R_and_grad(xc)
            return -R, -g * (x > 0)
        try:
            res = minimize(f, h, jac=True, method='L-BFGS-B',
                           bounds=[(0, None)] * h.size,
                           options={'maxiter': maxiter, 'maxfun': maxfun,
                                    'ftol': 1e-17, 'gtol': 1e-13})
            cand = np.clip(res.x, 0, None)
            if cand.sum() > 0:
                cand = _rescale_maxL(cand)
            return cand
        except Exception:
            return h

    def coord_sweep(h, cur, n_passes):
        n = h.size
        for _ in range(n_passes):
            if time.process_time() > deadline - 0.1:
                return h, cur
            improved = False
            order = rng.permutation(n)
            for idx in order:
                if time.process_time() > deadline - 0.1:
                    return h, cur
                old = h[idx]
                hi = max(6.0 * old, 1.0)
                def neg_r(alpha):
                    h[idx] = alpha
                    return -R_of(h)
                try:
                    res = minimize_scalar(neg_r, bounds=(0.0, hi),
                                          method='bounded',
                                          options={'xatol': 1e-9})
                    cand = res.x
                    cand_r = -res.fun
                except Exception:
                    cand = old; cand_r = cur
                if cand_r > cur + 1e-15:
                    h[idx] = cand; cur = cand_r; improved = True
                else:
                    h[idx] = old
            if not improved:
                break
        return h, cur

    # Stage 1: try upsampling with interpolation (smoother, often better)
    # and repeat, then optimize at each level.
    def try_level(seed):
        cand = lb_opt(seed, 400, 600)
        rc = R_of(cand)
        return cand, rc

    # Repeatedly try to grow resolution
    stagnation = 0
    while time.process_time() < deadline - 0.8 and best.size < 60000:
        now = time.process_time()
        rem = deadline - now
        if rem < 1.0:
            break

        # Alternate interpolation and repeat upsampling, pick best
        fac = 2
        interp_seed = _upsample_interp(best, fac)
        rep_seed = np.repeat(best, fac)
        rep_seed = rep_seed / max(rep_seed.max(), 1e-30)

        half = now + 0.45 * rem
        h_int = lb_opt(interp_seed, 300, 400, half)
        r_int = R_of(h_int)
        h_rep = lb_opt(rep_seed, 300, 400, deadline - 0.4)
        r_rep = R_of(h_rep)

        improved = False
        if r_int > bestR + 1e-12:
            best, bestR = h_int.copy(), r_int
            improved = True
            print("interp N=%d R=%.7f" % (best.size, bestR))
        if r_rep > bestR + 1e-12:
            best, bestR = h_rep.copy(), r_rep
            improved = True
            print("repeat N=%d R=%.7f" % (best.size, bestR))

        if not improved:
            # try polishing current best harder before giving up
            cand = lb_opt(best, 2000, 4000)
            rc = R_of(cand)
            if rc > bestR + 1e-13:
                best, bestR = cand.copy(), rc
                print("repolish N=%d R=%.7f" % (best.size, bestR))
                improved = True

        if not improved:
            stagnation += 1
            if stagnation >= 2:
                break

    # Stage 2: heavy polish at best resolution
    if time.process_time() < deadline - 0.5:
        cand = lb_opt(best, 5000, 10000)
        rc = R_of(cand)
        if rc > bestR:
            best, bestR = cand.copy(), rc
            print("heavy polish R=%.7f (N=%d)" % (bestR, best.size))

    # Stage 3: coordinate sweep as last resort
    if time.process_time() < deadline - 0.3:
        h2, c2 = coord_sweep(best.copy(), bestR, 1)
        if c2 > bestR + 1e-13:
            best, bestR = h2, c2
            print("coord sweep R=%.7f (N=%d)" % (bestR, best.size))

    # Final polish
    if time.process_time() < deadline - 0.2:
        cand = lb_opt(best, 5000, 10000)
        rc = R_of(cand)
        if rc > bestR:
            best, bestR = cand.copy(), rc

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2*a + b)
    dq[1:] += (a + 2*b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _direct_obj_grad(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    e = np.exp(np.clip(beta * (Lf - mx), -50, 0))
    Z = e.sum()
    logM = mx + np.log(Z) / beta
    w = e / Z
    obj = -np.log(num) + 2.0 * np.log(s) + logM
    gLf = -dq / num + w
    grad = _backprop(gLf, h)
    grad += 2.0 / s
    return obj, grad


def run_direct(h0, beta, maxiter, maxfun, deadline):
    if time.process_time() >= deadline - 1.0:
        return h0
    def f(x):
        xc = np.clip(x, 0, None)
        o, g = _direct_obj_grad(xc, beta)
        return o, g * (x > 0)
    try:
        res = minimize(f, h0, jac=True, method='L-BFGS-B',
                       bounds=[(0, None)] * h0.size,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-18, 'gtol': 1e-14})
        return _rescale_maxL(res.x)
    except Exception:
        return h0


def _conv_pad(h, u):
    n = h.size
    if n > 1500:
        return fftconvolve(h, u)
    return np.convolve(h, u)


def _backprop_general(gL, h):
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _make_closures(h, active, n, num, dq, Lf, s, Lm):
    def hessp(x_active, v_active):
        u = np.zeros(n)
        u[active] = v_active
        conv_hu = _conv_pad(h, u)
        delta = np.zeros(2 * n + 1)
        delta[1:1 + (2 * n - 1)] = 2.0 * conv_hu
        gL2 = (2.0 / 3.0) * delta
        gL2[1:] += (1.0 / 3.0) * delta[:-1]
        gL2[:-1] += (1.0 / 3.0) * delta[1:]
        H_num = _backprop_general(gL2[1:-1], h)
        dq_grad = _backprop_general(dq[1:-1], h)
        dq_dot_delta = np.dot(dq, delta)
        H = -H_num / num + (dq_dot_delta / (num * num)) * dq_grad
        H += (-2.0 / (s * s)) * u.sum()
        return H[active]

    na = active.size

    def fun(x_active):
        xfull = np.zeros(n)
        xfull[active] = np.clip(x_active, 0, None)
        s2 = xfull.sum()
        if s2 <= 0:
            return 1e18, np.zeros(na)
        num2, dq2, Lf2 = _num_and_dq(xfull)
        m2 = int(np.argmax(Lf2))
        Lm2 = Lf2[m2]
        if Lm2 <= 0 or num2 <= 0:
            return 1e18, np.zeros(na)
        gLf2 = -dq2 / num2
        gLf2[m2] += 1.0 / Lm2
        g2 = _backprop(gLf2, xfull) + 2.0 / s2
        obj = -np.log(num2) + 2.0 * np.log(s2) + np.log(Lm2)
        return obj, g2[active]

    return fun, hessp


def _newton_polish(h, deadline, max_steps=40):
    """Newton-CG on exact log-R with frozen argmax knot; returns improved h."""
    n = h.size
    for _ in range(max_steps):
        if time.process_time() >= deadline - 1.0:
            break
        h = _rescale_maxL(h)
        num, dq, Lf = _num_and_dq(h)
        m = int(np.argmax(Lf))
        Lm = Lf[m]
        s = h.sum()
        if Lm <= 0 or num <= 0 or s <= 0:
            break
        active = np.flatnonzero(h > 1e-14 * h.max())
        if active.size == 0:
            break
        fun, hessp = _make_closures(h, active, n, num, dq, Lf, s, Lm)
        x0 = h[active]
        try:
            res = minimize(fun, x0, jac=True, method='Newton-CG',
                           hessp=hessp,
                           options={'maxiter': 30, 'xtol': 1e-14})
        except Exception:
            break
        hnew = np.zeros(n)
        hnew[active] = np.clip(res.x, 0, None)
        r_old = R_of(h)
        hnew = _rescale_maxL(hnew)
        r_new = R_of(hnew)
        if r_new <= r_old + 1e-15:
            break
        h = hnew
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.6f (N=%d)" % (bestR, best.size))

    # Newton-CG polish of the start (the main new component).
    if time.process_time() < deadline - 2.0:
        h = _newton_polish(best.copy(), deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            print("newton R=%.7f" % bestR)

    # LSE polish ladder
    for beta in [200, 1000, 5000, 20000, 80000]:
        if time.process_time() >= deadline - 1.0:
            break
        h = run_direct(best, beta, 300, 600, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            print("lse%d R=%.7f" % (beta, bestR))

    # alternate Newton-CG and LSE polish until convergence
    for _ in range(30):
        if time.process_time() >= deadline - 1.0:
            break
        h = _newton_polish(best.copy(), deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            print("newton R=%.7f" % bestR)
        else:
            break
        if time.process_time() >= deadline - 1.0:
            break
        h = run_direct(best, 50000, 300, 600, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            print("lsehi R=%.7f" % bestR)
        else:
            break

    print("final R=%.6f (N=%d)" % (bestR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2*a + b)
    dq[1:] += (a + 2*b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _direct_obj_grad(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    e = np.exp(np.clip(beta * (Lf - mx), -50, 0))
    Z = e.sum()
    logM = mx + np.log(Z) / beta
    w = e / Z
    obj = -np.log(num) + 2.0 * np.log(s) + logM
    gLf = -dq / num + w
    grad = _backprop(gLf, h)
    grad += 2.0 / s
    return obj, grad


def run_direct(h0, beta, maxiter, maxfun, deadline):
    if time.process_time() >= deadline - 0.5:
        return h0
    def f(x):
        xc = np.clip(x, 0, None)
        o, g = _direct_obj_grad(xc, beta)
        return o, g * (x > 0)
    try:
        res = minimize(f, h0, jac=True, method='L-BFGS-B',
                       bounds=[(0, None)] * h0.size,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-17, 'gtol': 1e-13})
        return _rescale_maxL(res.x)
    except Exception:
        return h0


def _exact_obj_grad(h):
    """Objective = -log(num) + 2 log(s) + log(max L); gradient w.r.t. h.
    Uses the true argmax index (subgradient)."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    if Lm <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h)
    grad += 2.0 / s
    obj = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return obj, grad


def run_exact(h0, maxiter, maxfun, deadline):
    if time.process_time() >= deadline - 0.5:
        return h0
    def f(x):
        xc = np.clip(x, 0, None)
        o, g = _exact_obj_grad(xc)
        return o, g * (x > 0)
    try:
        res = minimize(f, h0, jac=True, method='L-BFGS-B',
                       bounds=[(0, None)] * h0.size,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-17, 'gtol': 1e-13})
        return _rescale_maxL(res.x)
    except Exception:
        return h0


def _local_refine(h, nsplit=4000):
    """ZOH-double the cells with largest |height| and near the peak."""
    n = h.size
    if n < 4 or n >= 190000:
        return h.copy()
    nsplit = min(nsplit, 190000 - n)
    if nsplit <= 0:
        return h.copy()
    _, _, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    # score: height + proximity to peak
    score = h.copy()
    # boost cells near peak
    lo = max(0, m - 300); hi = min(n, m + 300)
    score[lo:hi] *= 3.0
    idx = np.argpartition(-score, nsplit - 1)[:nsplit]
    sel = np.zeros(n, dtype=bool)
    sel[idx] = True
    new_n = n + int(sel.sum())
    h2 = np.empty(new_n, dtype=float)
    pos = 0
    for i in range(n):
        if sel[i]:
            h2[pos] = h[i]; h2[pos + 1] = h[i]
            pos += 2
        else:
            h2[pos] = h[i]
            pos += 1
    return h2


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.86

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    # Stage A: exact-argmax polish on current grid
    if time.process_time() < deadline - 1.0:
        h = run_exact(best, 400, 800, deadline)
        r = R_of(h)
        if r > bestR + 1e-13:
            best, bestR = h.copy(), r
            print("exact A R=%.7f" % bestR)

    # Stage B: ZOH refine (double grid) + exact polish, repeat
    for rnd in range(3):
        if time.process_time() >= deadline - 2.0:
            break
        # save current best at coarse grid
        n_cur = best.size
        if n_cur >= 190000:
            break
        h2 = _local_refine(best, nsplit=min(4000, 190000 - n_cur))
        if h2.size == best.size:
            break
        h2 = _rescale_maxL(h2)
        r2 = R_of(h2)
        print("refine%d R=%.7f (N=%d)" % (rnd, r2, h2.size))
        # polish on refined grid
        h3 = run_exact(h2, 400, 800, deadline)
        r3 = R_of(h3)
        if r3 > bestR + 1e-13:
            best, bestR = h3.copy(), r3
            print("refined accepted R=%.7f (N=%d)" % (bestR, best.size))
        else:
            # keep refined grid anyway if close, to allow further refinement
            if r2 > bestR - 1e-7:
                best, bestR = h2, r2
            break

    # Stage C: alternating exact-argmax and LSE polish with tight tolerances
    beta_list = [300, 1000, 3000, 10000]
    while time.process_time() < deadline - 1.0:
        improved = False
        h = best.copy()
        cur = bestR
        # exact polish
        if time.process_time() < deadline - 1.0:
            h = run_exact(h, 300, 600, deadline)
            r = R_of(h)
            if r > cur + 1e-13:
                cur = r; improved = True
        # LSE ramp
        for beta in beta_list:
            if time.process_time() >= deadline - 1.0:
                break
