                best, bestR = h.copy(), r
        if bestR - prev < 1e-13:
            break

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _direct_obj_grad(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    e = np.exp(np.clip(beta * (Lf - mx), -50, 0))
    Z = e.sum()
    logM = mx + np.log(Z) / beta
    w = e / Z
    obj = -np.log(num) + 2.0 * np.log(s) + logM
    gLf = -dq / num + w
    grad = _backprop(gLf, h)
    grad += 2.0 / s
    return obj, grad


def run_direct(h0, beta, maxiter, maxfun, deadline):
    if time.process_time() >= deadline - 1.0:
        return h0
    def f(x):
        xc = np.clip(x, 0, None)
        o, g = _direct_obj_grad(xc, beta)
        return o, g * (x > 0)
    try:
        res = minimize(f, h0, jac=True, method='L-BFGS-B',
                       bounds=[(0, None)] * h0.size,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-17, 'gtol': 1e-13})
        return _rescale_maxL(res.x)
    except Exception:
        return h0


def _refine_grid(h, factor):
    # Linear interpolation refinement: upsample h by factor
    n = h.size
    m = (n - 1) * factor + 1
    xo = np.linspace(0, 1, n)
    xn = np.linspace(0, 1, m)
    return np.interp(xn, xo, h)


def _coarsen_grid(h, factor):
    n = h.size
    if factor <= 1 or n <= factor:
        return h
    m = (n - 1) // factor + 1
    xo = np.linspace(0, 1, n)
    xn = np.linspace(0, 1, m)
    return np.interp(xn, xo, h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = base / base.max()

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.6f (N=%d)" % (bestR, best.size))

    def polish(h, cur, betas, iters):
        for beta, mi in zip(betas, iters):
            if time.process_time() >= deadline - 1.0:
                break
            h2 = run_direct(h, beta, mi, 2 * mi, deadline)
            r2 = R_of(h2)
            if r2 > cur + 1e-14:
                h, cur = h2, r2
        return h, cur

    # Phase 1: sharpen on current grid
    betas = [100, 300, 1000, 3000, 10000, 30000, 100000]
    iters = [300, 300, 400, 500, 600, 800, 1000]

    h = best.copy()
    cur = bestR
    h, cur = polish(h, cur, betas, iters)
    if cur > bestR + 1e-14:
        best, bestR = h.copy(), cur
        print("phase1 R=%.6f" % bestR)

    # Phase 2: refine grid and re-polish
    for factor in [2, 2]:
        if time.process_time() >= deadline - 1.0:
            break
        if best.size * factor > 200000:
            break
        h2 = _refine_grid(best, factor)
        h2 = h2 / h2.max()
        r2 = R_of(h2)
        # Polish on refined grid
        h2, r2 = polish(h2, r2, betas, iters)
        if r2 > bestR + 1e-14:
            best, bestR = h2.copy(), r2
            print("refine x%d R=%.6f (N=%d)" % (factor, bestR, best.size))

    # Phase 3: coarsen and re-polish (sometimes helps escape local minima)
    for factor in [2, 2]:
        if time.process_time() >= deadline - 1.0:
            break
        if best.size // factor < 50:
            break
        h2 = _coarsen_grid(best, factor)
        h2 = h2 / h2.max()
        r2 = R_of(h2)
        h2, r2 = polish(h2, r2, betas, iters)
        # Refine back
        if time.process_time() >= deadline - 1.0:
            break
        h3 = _refine_grid(h2, factor)
        h3 = h3 / h3.max()
        r3 = R_of(h3)
        h3, r3 = polish(h3, r3, betas, iters)
        if r3 > bestR + 1e-14:
            best, bestR = h3.copy(), r3
            print("coarsen+refine R=%.6f (N=%d)" % (bestR, best.size))

    # Phase 4: final long polish with very sharp betas
    if time.process_time() < deadline - 1.0:
        h, cur = polish(best, bestR, [100000, 300000, 1000000], [1500, 1500, 1500])
        if cur > bestR + 1e-14:
            best, bestR = h.copy(), cur
            print("final polish R=%.6f" % bestR)

    print("final R=%.6f (N=%d)" % (bestR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2*a + b)
    dq[1:] += (a + 2*b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _direct_obj_grad(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    e = np.exp(np.clip(beta * (Lf - mx), -50, 0))
    Z = e.sum()
    logM = mx + np.log(Z) / beta
    w = e / Z
    obj = -np.log(num) + 2.0 * np.log(s) + logM
    gLf = -dq / num + w
    grad = _backprop(gLf, h)
    grad += 2.0 / s
    return obj, grad


def run_direct(h0, beta, maxiter, maxfun, deadline):
    if time.process_time() >= deadline - 0.5:
        return h0
    def f(x):
        xc = np.clip(x, 0, None)
        o, g = _direct_obj_grad(xc, beta)
        return o, g * (x > 0)
    try:
        res = minimize(f, h0, jac=True, method='L-BFGS-B',
                       bounds=[(0, None)] * h0.size,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-17, 'gtol': 1e-13})
        return _rescale_maxL(res.x)
    except Exception:
        return h0


def _exact_obj_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    if Lm <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h)
    grad += 2.0 / s
    obj = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return obj, grad


def run_exact(h0, maxiter, maxfun, deadline):
    if time.process_time() >= deadline - 0.5:
        return h0
    def f(x):
        xc = np.clip(x, 0, None)
        o, g = _exact_obj_grad(xc)
        return o, g * (x > 0)
    try:
        res = minimize(f, h0, jac=True, method='L-BFGS-B',
                       bounds=[(0, None)] * h0.size,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-17, 'gtol': 1e-13})
        return _rescale_maxL(res.x)
    except Exception:
        return h0


def _topk_obj_grad_u(u, k):
    """Objective in log-space u=log h: -log(num)+2log(s)+log(mean of top-k Lf).
    Gradient w.r.t. u via chain rule (dh/du = h)."""
    h = np.exp(np.clip(u, -30, 30))
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(u.size)
    num, dq, Lf = _num_and_dq(h)
    n = Lf.size
    kk = min(k, n)
    idx = np.argpartition(-Lf, kk - 1)[:kk]
    M = Lf[idx].mean()
    if M <= 0:
        return 1e18, np.zeros(u.size)
    gLf = -dq / num
    gLf[idx] += 1.0 / (kk * M)
    grad_h = _backprop(gLf, h)
    grad_h += 2.0 / s
    grad_u = grad_h * h
    obj = -np.log(num) + 2.0 * np.log(s) + np.log(M)
    return obj, grad_u


def run_topk(h0, k, maxiter, deadline):
    if time.process_time() >= deadline - 0.5:
        return h0
    h0 = np.clip(h0, 0, None)
    if h0.sum() <= 0:
        return h0
    # active set: positive entries
    act = h0 > 0
    if act.sum() == 0:
        return h0
    u0 = np.log(np.maximum(h0[act], 1e-30))
    def f(u):
        full = np.full(h0.size, -30.0)
        full[act] = np.clip(u, -30, 30)
        o, g = _topk_obj_grad_u(full, k)
        return o, g[act]
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30, 30)] * u0.size,
                       options={'maxiter': maxiter, 'maxfun': maxiter * 3,
                                'ftol': 1e-17, 'gtol': 1e-13})
        h = h0.copy()
        h[act] = np.exp(np.clip(res.x, -30, 30))
        return _rescale_maxL(h)
    except Exception:
        return h0


def _local_refine(h, nsplit=4000):
    n = h.size
    if n < 4 or n >= 190000:
        return h.copy()
    nsplit = min(nsplit, 190000 - n)
    if nsplit <= 0:
        return h.copy()
    _, _, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    score = h.copy()
    lo = max(0, m - 300); hi = min(n, m + 300)
    score[lo:hi] *= 3.0
    idx = np.argpartition(-score, nsplit - 1)[:nsplit]
    sel = np.zeros(n, dtype=bool)
    sel[idx] = True
    new_n = n + int(sel.sum())
    h2 = np.empty(new_n, dtype=float)
    pos = 0
    for i in range(n):
        if sel[i]:
            h2[pos] = h[i]; h2[pos + 1] = h[i]
            pos += 2
        else:
            h2[pos] = h[i]
            pos += 1
    return h2


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    # Stage A: exact-argmax polish on current grid
    if time.process_time() < deadline - 1.0:
        h = run_exact(best, 400, 800, deadline)
        r = R_of(h)
        if r > bestR + 1e-13:
            best, bestR = h.copy(), r
            print("exact A R=%.7f" % bestR)

    # Stage B: ZOH refine (double grid) + exact polish
    for rnd in range(3):
        if time.process_time() >= deadline - 2.0:
            break
        n_cur = best.size
        if n_cur >= 190000:
            break
        h2 = _local_refine(best, nsplit=min(4000, 190000 - n_cur))
        if h2.size == best.size:
            break
        h2 = _rescale_maxL(h2)
        r2 = R_of(h2)
        print("refine%d R=%.7f (N=%d)" % (rnd, r2, h2.size))
        h3 = run_exact(h2, 400, 800, deadline)
        r3 = R_of(h3)
        if r3 > bestR + 1e-13:
            best, bestR = h3.copy(), r3
            print("refined accepted R=%.7f (N=%d)" % (bestR, best.size))
        else:
            if r2 > bestR - 1e-7:
                best, bestR = h2, r2
            break

    # Stage C: top-k average-max ladder + exact polish, alternating
    k_list = [16, 8, 4, 2]
    while time.process_time() < deadline - 1.0:
        improved = False
        h = best.copy()
        cur = bestR
        # exact polish
        if time.process_time() < deadline - 1.0:
            h = run_exact(h, 400, 800, deadline)
            r = R_of(h)
            if r > cur + 1e-13:
                cur = r; improved = True
        # top-k ladder
        for k in k_list:
            if time.process_time() >= deadline - 1.0:
                break
            h = run_topk(h, k, 400, deadline)
            r = R_of(h)
            if r > cur + 1e-13:
                cur = r; improved = True
            # exact pass after each k
            if time.process_time() < deadline - 1.0:
                h2 = run_exact(h, 400, 800, deadline)
                r2 = R_of(h2)
                if r2 > cur + 1e-13:
                    h = h2; cur = r2; improved = True
        if cur > bestR + 1e-13:
            best, bestR = h.copy(), cur
            print("polish R=%.7f (N=%d)" % (bestR, best.size))
        if not improved:
            break

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

