def _topk_obj_grad(h, k):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    n = Lf.size
    k = min(k, n)
    if k >= n:
        S = np.arange(n)
    else:
        S = np.argpartition(Lf, n - k)[n - k:]
    M = Lf[S].mean()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    obj = -np.log(num) + 2.0 * np.log(s) + np.log(M)
