        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2*a + b)
    dq[1:] += (a + 2*b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _direct_obj_grad(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    e = np.exp(np.clip(beta * (Lf - mx), -50, 0))
    Z = e.sum()
    logM = mx + np.log(Z) / beta
    w = e / Z
    obj = -np.log(num) + 2.0 * np.log(s) + logM
    gLf = -dq / num + w
    grad = _backprop(gLf, h)
    grad += 2.0 / s
    return obj, grad


def run_direct(h0, beta, maxiter, maxfun, deadline):
    if time.process_time() >= deadline - 1.0:
        return h0
    def f(x):
        xc = np.clip(x, 0, None)
        o, g = _direct_obj_grad(xc, beta)
        return o, g * (x > 0)
    try:
        res = minimize(f, h0, jac=True, method='L-BFGS-B',
                       bounds=[(0, None)] * h0.size,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-17, 'gtol': 1e-13})
        return _rescale_maxL(res.x)
    except Exception:
        return h0


def _norm_eq_grad(h):
    s = h.sum()
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    return grad


def _norm_eq_fun(h):
    s = h.sum()
    if s <= 0:
        return 1e18
    num, dq, Lf = _num_and_dq(h)
    return -np.log(num) + 2.0 * np.log(s) + np.log(Lf.max())


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None):
    if time.process_time() >= deadline - 1.0:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val = _norm_eq_fun(hh)
        g = _norm_eq_grad(hh)[active] * hh[active]
        return val, g

    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
        h2 = np.zeros(n)
        h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
        return _rescale_maxL(h2)
    except Exception:
        return h0


def _zoh_double(h):
    return np.repeat(h, 2)


def _block_avg(h, k):
    n = h.size
    m = n // k
    if m * k != n:
        h = h[:m * k]
    return h.reshape(m, k).mean(axis=1)


def _targeted_zoh(h, deadline):
    if time.process_time() >= deadline - 1.0:
        return h
    n = h.size
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    target = m / 2.0
    idx_near = np.argsort(np.abs(np.arange(n) - target))[:500]
    idx_tall = np.argsort(-h)[:min(1500, n)]
    split_set = np.unique(np.concatenate([idx_near, idx_tall]))
    split_set = split_set[(split_set >= 0) & (split_set < n)]

    h2 = np.repeat(h, 2)
    free = np.concatenate([2 * split_set, 2 * split_set + 1])
    free = np.unique(free)
    h2 = _rescale_maxL(h2)
    h3 = _exact_lbfgs(h2, 400, 800, deadline, free=free)
    if R_of(h3) > R_of(h2) + 1e-15:
        return h3
    return h2


def _perturb(h, scale, rng):
    h = h.copy()
    nz = np.flatnonzero(h > 0)
    if nz.size == 0:
        return h
    u = rng.normal(0.0, scale, size=nz.size)
    u -= u.mean()
    h[nz] = h[nz] * np.exp(u)
    return _rescale_maxL(h)


def _low_ladder(h0, deadline):
    """Softmax ladder at low res."""
    h = h0
    best = h.copy()
    bestR = R_of(best)
    for beta in [200, 1000, 5000, 20000]:
        if time.process_time() >= deadline - 2.0:
            break
        h = run_direct(h, beta, 400, 800, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.6f (N=%d)" % (bestR, best.size))

    N0 = base.size

    # downsample by 4
    if N0 % 4 == 0 and N0 >= 8:
        low0 = _rescale_maxL(_block_avg(base, 4))
    else:
        low0 = base.copy()
    print("downsampled to N=%d R=%.7f" % (low0.size, R_of(low0)))

    rng = np.random.default_rng(12345)
    scales = [0.0, 0.05, 0.15, 0.30]

    best_low = low0.copy()
    best_lowR = R_of(best_low)
    best_full = None
    best_fullR = -1.0

    for si, sc in enumerate(scales):
        if time.process_time() >= deadline - 3.0:
            break
        seed = low0.copy() if sc == 0.0 else _perturb(low0, sc, rng)
        low, lowR = _low_ladder(seed, deadline)
        print("seed %d (scale=%.2f) low R=%.7f" % (si, sc, lowR))
        if lowR > best_lowR + 1e-15:
            best_low, best_lowR = low.copy(), lowR

        # targeted ZOH round
        if time.process_time() < deadline - 3.0:
            h = _targeted_zoh(low, deadline)
            r = R_of(h)
            if r > lowR + 1e-15:
                low, lowR = h, r
                print("  zoh low R=%.7f (N=%d)" % (lowR, low.size))

        # redouble to N0 and short exact pass
        cand = low
        while cand.size < N0:
            cand = _zoh_double(cand)
        if cand.size > N0:
            cand = cand[:N0]
        cand = _rescale_maxL(cand)
        if time.process_time() < deadline - 2.0:
            cand = _exact_lbfgs(cand, 200, 400, deadline)
        r = R_of(cand)
        print("  redoubled R=%.7f (N=%d)" % (r, cand.size))
        if r > best_fullR + 1e-15:
            best_full, best_fullR = cand.copy(), r

    # adopt best full-res into overall best
    if best_full is not None and best_fullR > bestR + 1e-15:
        best, bestR = best_full.copy(), best_fullR
        print("best full R=%.7f" % bestR)

    # p0234 finishing: exact-argmax L-BFGS at full res
    if time.process_time() < deadline - 1.0:
        h = _exact_lbfgs(best, 800, 1600, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            print("full exact R=%.7f" % bestR)

    # LSE ladder at full res
    for beta in [2000, 5000, 20000, 100000]:
        if time.process_time() >= deadline - 0.5:
            break
        h = run_direct(best, beta, 300, 600, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            print("full lse beta=%d R=%.7f" % (beta, bestR))

    # one final exact pass
    if time.process_time() < deadline - 0.5:
        h = _exact_lbfgs(best, 400, 800, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            print("final exact R=%.7f" % bestR)

    if bestR < R_of(base):
        best = base
        bestR = R_of(base)

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best
